arguments.file_text:
@page "/"

<PageTitle>Recipe Community</PageTitle>

<h1>🍳 Recipe Community</h1>
<p class="lead">Discover and share delicious recipes from around the world!</p>

<h2>Browse by Category</h2>
<div class="row">
    @foreach (var category in RecipeCommunity.Models.RecipeStore.GetCategories())
    {
        <div class="col-md-4 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@GetCategoryEmoji(category) @category</h5>
                    <p class="card-text">@RecipeCommunity.Models.RecipeStore.GetByCategory(category).Count() recipes</p>
                    <a href="/category/@category" class="btn btn-primary">Browse</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🍕",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Thai" => "🍜",
        "Desserts" => "🍰",
        "Salads" => "🥗",
        _ => "🍽️"
    };
}

@page "/category/{CategoryName}"

<PageTitle>@CategoryName Recipes - Recipe Community</PageTitle>

<h1>@CategoryName Recipes</h1>
<a href="/" class="btn btn-outline-secondary mb-3">← Back to Categories</a>

@if (recipes.Any())
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">
                            <span class="text-warning">@GetStars(recipe.AverageRating)</span>
                            <small class="text-muted">(@recipe.RatingCount ratings)</small>
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}
else
{
    <p class="text-muted">No recipes found in this category.</p>
}

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private IEnumerable<RecipeCommunity.Models.Recipe> recipes = Enumerable.Empty<RecipeCommunity.Models.Recipe>();

    protected override void OnParametersSet()
    {
        recipes = RecipeCommunity.Models.RecipeStore.GetByCategory(CategoryName);
    }

    private string GetStars(double rating)
    {
        int full = (int)rating;
        return new string('★', full) + new string('☆', 5 - full);
    }
}

@page "/recipe/{Id:int}"

<PageTitle>@(recipe?.Title ?? "Recipe") - Recipe Community</PageTitle>

@if (recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
    <a href="/" class="btn btn-primary">Back to Home</a>
}
else
{
    <a href="/category/@recipe.Category" class="btn btn-outline-secondary mb-3">← Back to @recipe.Category</a>

    <h1>@recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <div class="row mt-3">
        <div class="col-md-4">
            <div class="card">
                <div class="card-header"><strong>Ingredients</strong></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>
        <div class="col-md-8">
            <div class="card">
                <div class="card-header"><strong>Instructions</strong></div>
                <div class="card-body">
                    @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <p>@step</p>
                    }
                </div>
            </div>
        </div>
    </div>

    <div class="mt-4">
        <h4>Rate this Recipe</h4>
        <p class="text-muted">
            Current rating: @recipe.AverageRating.ToString("F1") / 5
            (@recipe.RatingCount ratings)
        </p>
        <StarRating RecipeId="@recipe.Id" />
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private RecipeCommunity.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeCommunity.Models.RecipeStore.GetById(Id);
    }
}

@page "/submit"
@using RecipeCommunity.Models

<PageTitle>Submit a Recipe - Recipe Community</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

<SubmitRecipeForm />

@rendermode InteractiveServer
@using RecipeCommunity.Models

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= (hoverRating > 0 ? hoverRating : selectedRating) ? "filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => hoverRating = star"
              @onmouseout="() => hoverRating = 0"
              role="button">
            @(star <= (hoverRating > 0 ? hoverRating : selectedRating) ? "★" : "☆")
        </span>
    }
    @if (submitted)
    {
        <span class="ms-2 text-success">✓ Thanks for rating!</span>
    }
</div>

<style>
    .star-rating .star {
        font-size: 1.8rem;
        cursor: pointer;
        color: #ffc107;
        transition: transform 0.1s;
    }
    .star-rating .star:hover {
        transform: scale(1.2);
    }
</style>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int selectedRating;
    private int hoverRating;
    private bool submitted;

    private void Rate(int stars)
    {
        selectedRating = stars;
        submitted = true;
        RecipeStore.AddRating(RecipeId, stars);
    }
}

@rendermode InteractiveServer
@using RecipeCommunity.Models
@inject NavigationManager Navigation

@if (submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe "@submission.Title" has been added.
        <a href="/" class="alert-link">Back to Home</a>
    </div>
}
else
{
    <EditForm Model="submission" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <div class="row">
            <div class="col-md-8">
                <div class="mb-3">
                    <label class="form-label">Recipe Title</label>
                    <InputText @bind-Value="submission.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Category</label>
                    <InputSelect @bind-Value="submission.Category" class="form-select">
                        <option value="">Select a category...</option>
                        <option value="Italian">Italian</option>
                        <option value="Indian">Indian</option>
                        <option value="Mexican">Mexican</option>
                        <option value="Thai">Thai</option>
                        <option value="Desserts">Desserts</option>
                        <option value="Salads">Salads</option>
                        <option value="Other">Other</option>
                    </InputSelect>
                </div>

                <div class="mb-3">
                    <label class="form-label">Ingredients (one per line)</label>
                    <InputTextArea @bind-Value="submission.Ingredients" class="form-control" rows="6"
                        placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Steps (one per line)</label>
                    <InputTextArea @bind-Value="submission.Steps" class="form-control" rows="8"
                        placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients&#10;3. Add wet ingredients" />
                </div>

                <button type="submit" class="btn btn-success btn-lg"
                    disabled="@(string.IsNullOrWhiteSpace(submission.Title) || string.IsNullOrWhiteSpace(submission.Category))">
                    Submit Recipe
                </button>
            </div>
        </div>
    </EditForm>
}

@code {
    private RecipeSubmission submission = new();
    private bool submitted;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(submission.Title) || string.IsNullOrWhiteSpace(submission.Category))
            return;

        RecipeStore.Add(submission);
        submitted = true;
    }
}

