@page "/"

<PageTitle>Recipe Community</PageTitle>

<h1>🍳 Recipe Community</h1>
<p class="lead">Discover and share delicious recipes from around the world!</p>

<h2>Browse by Category</h2>
<div class="row">
    @foreach (var category in RecipeCommunity.Models.RecipeStore.GetCategories())
    {
        <div class="col-md-4 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@GetCategoryEmoji(category) @category</h5>
                    <p class="card-text">@RecipeCommunity.Models.RecipeStore.GetByCategory(category).Count() recipes</p>
                    <a href="/category/@category" class="btn btn-primary">Browse</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🍕",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Thai" => "🍜",
        "Desserts" => "🍰",
        "Salads" => "🥗",
        _ => "🍽️"
    };
}

@page "/category/{CategoryName}"

<PageTitle>@CategoryName Recipes - Recipe Community</PageTitle>

<h1>@CategoryName Recipes</h1>
<a href="/" class="btn btn-outline-secondary mb-3">← Back to Categories</a>

@if (recipes.Any())
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">
                            <span class="text-warning">@GetStars(recipe.AverageRating)</span>
                            <small class="text-muted">(@recipe.RatingCount ratings)</small>
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}
else
{
    <p class="text-muted">No recipes found in this category.</p>
}

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private IEnumerable<RecipeCommunity.Models.Recipe> recipes = Enumerable.Empty<RecipeCommunity.Models.Recipe>();

    protected override void OnParametersSet()
    {
        recipes = RecipeCommunity.Models.RecipeStore.GetByCategory(CategoryName);
    }

    private string GetStars(double rating)
    {
        int full = (int)rating;
        return new string('★', full) + new string('☆', 5 - full);
    }
}

